    .choice:hover {
      border-color: rgba(147, 197, 253, 0.4);
      background: rgba(255, 255, 255, 0.04);
      transform: translateY(-1px);
    }

    .choice input {
      margin-top: 3px;
      width: 18px;
      height: 18px;
