 </head>
 <body>
   <main class="quiz-shell">
     <header>
       <h1>Computer Languages Quiz</h1>
       <p class="subtitle">Select every answer that applies for each question.</p>
     </header>

     <form id="quiz-form" novalidate>
       <div class="form-field">
         <h2 class="question-title">1. Which of these are programming languages?</h2>
         <p class="help-text">Choose all options that are widely used to write software.</p>
         <ul class="choices">
           <li class="choice"><input type="checkbox" id="q1-a" name="q1" value="Python"><label for="q1-a">Python</label></li>
           <li class="choice"><input type="checkbox" id="q1-b" name="q1" value="HTML"><label for="q1-b">HTML</label></li>
           <li class="choice"><input type="checkbox" id="q1-c" name="q1" value="JavaScript"><label for="q1-c">JavaScript</label></li>
           <li class="choice"><input type="checkbox" id="q1-d" name="q1" value="CSS"><label for="q1-d">CSS</label></li>
         </ul>
       </div>

       <div class="form-field">
         <h2 class="question-title">2. Which of these are low-level or systems-oriented languages?</h2>
         <ul class="choices">
           <li class="choice"><input type="checkbox" id="q2-a" name="q2" value="C"><label for="q2-a">C</label></li>
           <li class="choice"><input type="checkbox" id="q2-b" name="q2" value="Rust"><label for="q2-b">Rust</label></li>
           <li class="choice"><input type="checkbox" id="q2-c" name="q2" value="Ruby"><label for="q2-c">Ruby</label></li>
           <li class="choice"><input type="checkbox" id="q2-d" name="q2" value="Assembly"><label for="q2-d">Assembly</label></li>
         </ul>
       </div>

       <div class="form-field">
         <h2 class="question-title">3. Which of these are used as compiled languages?</h2>
         <ul class="choices">
           <li class="choice"><input type="checkbox" id="q3-a" name="q3" value="Go"><label for="q3-a">Go</label></li>
           <li class="choice"><input type="checkbox" id="q3-b" name="q3" value="Java"><label for="q3-b">Java</label></li>
           <li class="choice"><input type="checkbox" id="q3-c" name="q3" value="SQL"><label for="q3-c">SQL</label></li>
           <li class="choice"><input type="checkbox" id="q3-d" name="q3" value="C++"><label for="q3-d">C++</label></li>
         </ul>
       </div>

       <div class="actions">
         <button type="submit">Submit Quiz</button>
         <div class="result" id="result" aria-live="polite"></div>
       </div>
     </form>
   </main>

   <script>
     const answers = {
       q1: ["Python", "JavaScript"],
       q2: ["C", "Rust", "Assembly"],
       q3: ["Go", "Java", "C++"]
     };

     const form = document.getElementById("quiz-form");
     const result = document.getElementById("result");

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       let correctQuestions = 0;

       Object.keys(answers).forEach((questionName) => {
         const selected = [...form.querySelectorAll(`input[name="${questionName}"]:checked`)].map((input) => input.value).sort();
         const expected = [...answers[questionName]].sort();

         if (selected.length === expected.length && selected.every((value, index) => value === expected[index])) {
           correctQuestions += 1;
         }
       });

       result.textContent = `You scored ${correctQuestions} out of 3.`;
     });
   </script>
 </body>
 </html>

